113	    /// Construct a parser from an exact name.
114	    pub fn create(&self, name: &str, tools: &[ChatTool]) -> crate::Result<Box<dyn ToolParser>> {
115	        let creator = self.creator(name).ok_or_else(|| crate::Error::ParserUnavailableByName {
116	            kind: "tool",
117	            name: name.to_string(),
118	            available_names: self.list(),
119	        })?;
120	
121	        creator(tools).map_err(|error| crate::Error::ParserInitialization {
122	            kind: "tool",
123	            name: name.to_string(),
124	            error: error.into(),
125	        })
126	    }
127	
128	    /// Resolve a parser from model ID and then construct it.
129	    pub fn create_for_model(
130	        &self,
131	        model_id: &str,
132	        tools: &[ChatTool],
133	    ) -> crate::Result<Box<dyn ToolParser>> {
134	        let name = self.resolve_name_for_model(model_id).ok_or_else(|| {
135	            crate::Error::ParserUnavailableForModel {
136	                kind: "tool",
137	                model_id: model_id.to_string(),
138	            }
139	        })?;
140	        self.create(name, tools)
141	    }
142	}
