27	#[derive(Debug, Clone, Copy)]
28	struct JsonToolCallConfig {
29	    parser_name: &'static str,
30	    start_marker: &'static str,
31	    end_marker: &'static str,
32	    marker_whitespace: JsonToolCallWhitespace,
33	    delimiter: Option<&'static str>,
34	    name_key: &'static str,
35	    arguments_key: &'static str,
36	}
37	
38	#[derive(Debug, Clone, Copy)]
39	enum JsonToolCallWhitespace {
40	    Optional,
41	    Exact(&'static str),
42	}
43	
44	#[derive(Debug, Clone, PartialEq, Eq)]
45	enum JsonToolCallMode {
46	    Text,
47	    Header,
48	    Arguments { json_scan: JsonObjectScanState },
49	}
50	
51	#[derive(Debug, Clone, PartialEq, Eq)]
52	enum JsonToolCallEvent {
53	    Text { len: usize },
54	    ToolCallStart,
55	    ToolCallHeader { function_name: String },
56	    Arguments { len: usize },
57	    ToolCallDelimiter,
58	    ToolCallEnd,
59	}
