61	/// Tool parser core for marker-wrapped JSON tool calls.
62	#[derive(Debug)]
63	struct JsonToolCallParser {
64	    config: JsonToolCallConfig,
65	    buffer: String,
66	    mode: JsonToolCallMode,
67	    active_tool_index: Option<usize>,
68	    emitted_tool_count: usize,
69	}
70	
71	impl JsonToolCallParser {
72	    /// Create a marker-wrapped JSON tool-call parser.
73	    fn new(config: JsonToolCallConfig) -> Self {
74	        Self {
75	            config,
76	            buffer: String::new(),
77	            mode: JsonToolCallMode::Text,
78	            active_tool_index: None,
79	            emitted_tool_count: 0,
80	        }
81	    }
82	
83	    fn parse_into(&mut self, chunk: &str, output: &mut ToolParserOutput) -> Result<()> {
84	        self.buffer.push_str(chunk);
85	        let config = self.config;
86	
87	        while let Some((event, consumed_len)) = parse_buffered_event(&self.buffer, |input| {
88	            parse_next_json_tool_call_event(input, &mut self.mode, config)
89	        })? {
90	            self.apply_event(event, output)?;
91	            self.buffer.drain(..consumed_len);
92	        }
93	
94	        Ok(())
95	    }
96	
97	    fn finish(&mut self) -> Result<ToolParserOutput> {
98	        let mut output = ToolParserOutput::default();
99	        match &self.mode {
100	            JsonToolCallMode::Text => output.normal_text.push_str(&self.buffer),
101	            JsonToolCallMode::Header | JsonToolCallMode::Arguments { .. } => {
102	                return Err(parsing_failed!(
103	                    "incomplete {} tool call",
104	                    self.config.parser_name
105	                ));
106	            }
107	        }
108	        let _ = self.reset();
109	        Ok(output)
110	    }
111	
112	    /// Apply one parsed JSON tool-call event to parser state and output.
113	    fn apply_event(
114	        &mut self,
115	        event: JsonToolCallEvent,
116	        output: &mut ToolParserOutput,
117	    ) -> Result<()> {
118	        match event {
119	            JsonToolCallEvent::Text { len: consumed_len } => {
120	                output.normal_text.push_str(&self.buffer[..consumed_len]);
121	            }
122	            JsonToolCallEvent::ToolCallStart => self.mode = JsonToolCallMode::Header,
123	            JsonToolCallEvent::ToolCallHeader { function_name } => {
124	                let tool_index = self.emitted_tool_count;
125	                self.emitted_tool_count += 1;
126	                self.active_tool_index = Some(tool_index);
127	                self.mode = JsonToolCallMode::Arguments {
128	                    json_scan: JsonObjectScanState::default(),
129	                };
130	                output.calls.push(ToolCallDelta {
131	                    tool_index,
132	                    name: Some(function_name),
133	                    arguments: String::new(),
134	                });
135	            }
136	            JsonToolCallEvent::Arguments { len: consumed_len } => {
137	                let Some(tool_index) = self.active_tool_index else {
138	                    return Err(parsing_failed!(
139	                        "{} arguments without an active tool call",
140	                        self.config.parser_name
141	                    ));
142	                };
143	                output.calls.push(ToolCallDelta {
144	                    tool_index,
145	                    name: None,
146	                    arguments: self.buffer[..consumed_len].to_string(),
147	                });
148	            }
149	            JsonToolCallEvent::ToolCallDelimiter => {
150	                self.active_tool_index = None;
151	                self.mode = JsonToolCallMode::Header;
152	            }
153	            JsonToolCallEvent::ToolCallEnd => {
154	                self.active_tool_index = None;
155	                self.mode = JsonToolCallMode::Text;
156	            }
157	        }
158	        Ok(())
159	    }
160	
161	    fn reset(&mut self) -> String {
162	        self.mode = JsonToolCallMode::Text;
163	        self.active_tool_index = None;
164	        self.emitted_tool_count = 0;
165	        std::mem::take(&mut self.buffer)
166	    }
167	}
