4	const HERMES_CONFIG: JsonToolCallConfig = JsonToolCallConfig {
5	    parser_name: "Hermes",
6	    start_marker: "<tool_call>",
7	    end_marker: "</tool_call>",
8	    marker_whitespace: JsonToolCallWhitespace::Optional,
9	    delimiter: None,
10	    name_key: "name",
11	    arguments_key: "arguments",
12	};
