14	/// Tool parser for Hermes XML-wrapped JSON tool calls.
15	///
16	/// Example tool call content:
17	///
18	/// ```text
19	/// <tool_call>{"name": "get_weather", "arguments": {"location":"Tokyo"}}</tool_call>
20	/// ```
21	///
22	/// Arguments are already OpenAI-style JSON text, so they are streamed as raw
23	/// argument deltas without schema conversion or JSON normalization.
24	///
25	/// Note: parallel calls are represented as repeated
26	/// `<tool_call>...</tool_call>` blocks, not as multiple calls inside one tag.
27	pub struct HermesToolParser {
28	    inner: JsonToolCallParser,
29	}
30	
31	impl HermesToolParser {
32	    /// Create a Hermes tool parser.
33	    fn new(_tools: &[Tool]) -> Self {
34	        Self {
35	            inner: JsonToolCallParser::new(HERMES_CONFIG),
36	        }
37	    }
38	}
39	
40	impl ToolParser for HermesToolParser {
41	    fn create(tools: &[Tool]) -> Result<Box<dyn ToolParser>>
42	    where
43	        Self: Sized + 'static,
44	    {
45	        Ok(Box::new(Self::new(tools)))
46	    }
47	
48	    fn parse_into(&mut self, chunk: &str, output: &mut ToolParserOutput) -> Result<()> {
49	        self.inner.parse_into(chunk, output)
50	    }
51	
52	    fn finish(&mut self) -> Result<ToolParserOutput> {
53	        self.inner.finish()
54	    }
55	
56	    fn reset(&mut self) -> String {
57	        self.inner.reset()
58	    }
59	}
