43	/// One tool-call update emitted while parsing assistant text.
44	#[derive(Debug, Clone, PartialEq, Eq)]
45	pub struct ToolCallDelta {
46	    /// Stable parser-local tool index for this call within one assistant turn.
47	    pub tool_index: usize,
48	    /// Function name, present on the first update for one tool call.
49	    pub name: Option<String>,
50	    /// Arguments text contributed by this update.
51	    pub arguments: String,
52	}
53	
54	/// Result of advancing tool parsing with one assistant-text input.
55	#[derive(Debug, Clone, Default, PartialEq, Eq)]
56	pub struct ToolParserOutput {
57	    /// Plain assistant text that is not part of any tool call.
58	    pub normal_text: String,
59	    /// Tool-call updates extracted from this input.
60	    pub calls: Vec<ToolCallDelta>,
61	}
62	
63	impl ToolParserOutput {
64	    /// Append another parser output onto this one.
65	    ///
66	    /// Note that this does not attempt to merge multiple deltas for the same
67	    /// tool call into one complete item. Call `coalesce_calls()` after if
68	    /// that behavior is desired.
69	    pub fn append(&mut self, mut other: Self) {
70	        self.normal_text.push_str(&other.normal_text);
71	        self.calls.append(&mut other.calls);
72	    }
73	
74	    /// Merge multiple deltas for the same tool call into one complete item.
75	    ///
76	    /// This is primarily used by the default `parse_complete()` implementation,
77	    /// which delegates through the incremental parser lifecycle and then
78	    /// needs to collapse streaming-style argument fragments into one final
79	    /// tool call.
80	    pub fn coalesce_calls(mut self) -> Self {
81	        let mut merged = BTreeMap::<usize, ToolCallDelta>::new();
82	        let mut order = Vec::new();
83	
84	        for call in self.calls {
85	            match merged.entry(call.tool_index) {
86	                btree_map::Entry::Vacant(entry) => {
87	                    order.push(call.tool_index);
88	                    entry.insert(call);
89	                }
90	                btree_map::Entry::Occupied(mut entry) => {
91	                    let existing = entry.get_mut();
92	                    if existing.name.is_none() {
93	                        existing.name = call.name;
94	                    }
95	                    existing.arguments.push_str(&call.arguments);
96	                }
97	            }
98	        }
99	
100	        self.calls =
101	            order.into_iter().filter_map(|tool_index| merged.remove(&tool_index)).collect();
102	        self
103	    }
104	}
