106	/// Incremental parser that extracts tool calls from assistant output.
107	pub trait ToolParser: Send {
108	    /// Construct a boxed parser instance for one request stream.
109	    fn create(tools: &[Tool]) -> Result<Box<dyn ToolParser>>
110	    where
111	        Self: Sized + 'static;
112	
113	    /// Return whether decoded output must preserve tokenizer special tokens.
114	    ///
115	    /// Some model families emit tool-call sentinels as special tokens. Those
116	    /// parsers need `skip_special_tokens = false` while parsing is enabled.
117	    fn preserve_special_tokens(&self) -> bool {
118	        false
119	    }
120	
121	    /// Feed one decoded text delta into the parser, appending committed output
122	    /// into `output`.
123	    ///
124	    /// If this returns an error, any output already appended to `output`
125	    /// remains committed parser output. The parser must keep its uncommitted
126	    /// buffer intact so callers may recover it with `reset()`.
127	    fn parse_into(&mut self, chunk: &str, output: &mut ToolParserOutput) -> Result<()>;
128	
129	    /// Flush any buffered partial state at end of stream.
130	    ///
131	    /// This operation is atomic: on error no partial output is returned and the
132	    /// parser's buffered state is left intact.
133	    fn finish(&mut self) -> Result<ToolParserOutput>;
134	
135	    /// Clear parser state and return currently uncommitted buffered text.
136	    ///
137	    /// Callers may use this to recover any text that failed to parse after an error
138	    /// and output it as normal text.
139	    fn reset(&mut self) -> String;
140	}
141	
142	/// Extension methods for easily testing `ToolParser` implementations.
143	///
144	/// These helpers do not handle partial parsing or error recovery, so they are
145	/// not intended for use in production code paths.
146	#[cfg(any(test, feature = "test-util"))]
147	#[easy_ext::ext(ToolParserTestExt)]
148	impl<T: ToolParser + ?Sized> T {
149	    /// Feed one decoded text delta and return only if the whole chunk parses.
150	    ///
151	    /// If parsing fails, partial committed output is discarded by this helper.
152	    /// Prefer `parse_into` for more fine-grained control in error recovery.
153	    pub fn parse_chunk(&mut self, chunk: &str) -> Result<ToolParserOutput> {
154	        let mut output = ToolParserOutput::default();
155	        self.parse_into(chunk, &mut output)?;
156	        Ok(output)
157	    }
158	
159	    /// Parse complete tool calls from final output.
160	    ///
161	    /// This default implementation reuses the incremental parser lifecycle by
162	    /// feeding the full output through `parse_chunk()` and then calling `finish()`.
163	    ///
164	    /// If parsing fails, partial committed output is discarded by this helper.
165	    /// Prefer `parse_into` for more fine-grained control in error recovery.
166	    pub fn parse_complete(&mut self, text: &str) -> Result<ToolParserOutput> {
167	        let mut output = self.parse_chunk(text)?;
168	        output.append(self.finish()?);
169	        Ok(output.coalesce_calls())
170	    }
171	}
