57	/// Validate explicit parser override names without starting request processing.
58	pub fn validate_parser_overrides(
59	    tool_call_parser: &ParserSelection,
60	    reasoning_parser: &ParserSelection,
61	) -> Result<()> {
62	    let tool_parser_factory = ToolParserFactory::global();
63	    if let ParserSelection::Explicit(name) = tool_call_parser
64	        && !tool_parser_factory.contains(name)
65	    {
66	        return Err(Error::ParserUnavailableByName {
67	            kind: "tool",
68	            name: name.clone(),
69	            available_names: tool_parser_factory.list(),
70	        });
71	    }
72	
73	    let reasoning_parser_factory = ReasoningParserFactory::global();
74	    if let ParserSelection::Explicit(name) = reasoning_parser
75	        && !reasoning_parser_factory.contains(name)
76	    {
77	        return Err(Error::ParserUnavailableByName {
78	            kind: "reasoning",
79	            name: name.clone(),
80	            available_names: reasoning_parser_factory.list(),
81	        });
82	    }
83	
84	    Ok(())
85	}
