    fn internlm2_preserves_special_tokens() {
        let parser = Internlm2ToolParser::new(&test_tools());
        assert!(parser.preserve_special_tokens());
    }

    #[test]
    fn internlm2_parse_complete_without_tool_call_keeps_text() {
        let mut parser = Internlm2ToolParser::new(&test_tools());
        let output = parser.parse_complete("Hello, world!").unwrap();

        assert_eq!(output.normal_text, "Hello, world!");
        assert!(output.calls.is_empty());
    }

    #[test]
    fn internlm2_parse_complete_extracts_raw_json_parameters() {
        let mut parser = Internlm2ToolParser::new(&test_tools());
        let parameters = r#"{ "location": "Tokyo", "days": "3" }"#;
        let output = parser
            .parse_complete(&format!(
                "Let me check.\n{}",
                build_tool_call("get_weather", parameters)
            ))
            .unwrap();

        assert_eq!(output.normal_text, "Let me check.\n");
        assert_eq!(output.calls.len(), 1);
        assert_eq!(output.calls[0].tool_index, 0);
        assert_eq!(output.calls[0].name.as_deref(), Some("get_weather"));
        assert_eq!(output.calls[0].arguments, parameters);
    }

